<script setup lang="ts">
import {ref} from 'vue';import PageShell from '../../components/PageShell.vue';import OrderCard from '../../components/OrderCard.vue';import {usePage} from '../../composables/usePage';import {productApi} from '../../api/product';import {useUserStore} from '../../store/modules/user';import {token} from '../../utils/auth';import {go,money} from '../../utils/format'
const user=useUserStore(), orders=ref<any[]>([]),catalog=ref<any>({services:[]});const {loading,error,load}=usePage(async()=>{orders.value=[];if(token()&&!user.user)await user.restore();if(user.sitter){uni.reLaunch({url:'/pages/sitter/tasks'});return}try{catalog.value=await productApi.catalog()}catch{catalog.value={services:[]}}if(user.user){const o=await productApi.orders();orders.value=o.list.filter((x:any)=>['SERVICING','ACCEPTED','PENDING_ACCEPT','DISPATCHING'].includes(x.status))}},false)
</script>
